package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import br.com.admeclesial.domain.financeiro.TipoMovimentacaoFinanceira; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.UUID;
@Controller @RequestMapping("/relatorios/movimentacoes-financeiras") public class RelatorioMovimentacaoWebController { private final RelatorioMovimentacaoApplicationService service; private final RelatorioContextoService contexto; private final ContaFinanceiraRepository contas; private final CategoriaFinanceiraRepository categorias; private final CentroCustoRepository centros; public RelatorioMovimentacaoWebController(RelatorioMovimentacaoApplicationService s,RelatorioContextoService c,ContaFinanceiraRepository co,CategoriaFinanceiraRepository ca,CentroCustoRepository ce){service=s;contexto=c;contas=co;categorias=ca;centros=ce;}
 @GetMapping public String tela(@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataInicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataFim,@RequestParam(required=false) UUID contaUuid,@RequestParam(required=false) TipoMovimentacaoFinanceira tipo,@RequestParam(required=false) UUID categoriaUuid,@RequestParam(required=false) UUID centroCustoUuid,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,Model m){m.addAttribute("organizacoes",contexto.organizacoesAutorizadas());m.addAttribute("contas",contas.findAllByOrderByNomeAsc());m.addAttribute("categorias",categorias.findAllByOrderByNomeAsc());m.addAttribute("centros",centros.findAllByOrderByNomeAsc());m.addAttribute("tipos",TipoMovimentacaoFinanceira.values());m.addAttribute("organizacaoUuid",organizacaoUuid);m.addAttribute("dataInicio",dataInicio);m.addAttribute("dataFim",dataFim);m.addAttribute("contaUuid",contaUuid);m.addAttribute("tipo",tipo);m.addAttribute("categoriaUuid",categoriaUuid);m.addAttribute("centroCustoUuid",centroCustoUuid);if(organizacaoUuid!=null){var f=new RelatorioMovimentacaoFiltro(organizacaoUuid,dataInicio,dataFim,contaUuid,tipo,categoriaUuid,centroCustoUuid,pagina,tamanho);m.addAttribute("resultado",service.pesquisar(f));m.addAttribute("resumo",service.resumo(f));}return "relatorio/movimentacoes-financeiras";}
}
